'use strict';

/**
 * The test employee created by Step 1 of the full-module single run.
 *
 * Every run CREATES a brand-new employee and then searches the register for
 * that exact person. The person created in a run is carried through every
 * later module step of that run (leave → ESS → approval → sync → payroll).
 *
 * What CHANGES on every run (generated by forRun()):
 *   first name, display name, username, email, phone
 * What STAYS the same (edit here if you want different values):
 *   everything in `details` below.
 *
 * Names must be letters only (the form rejects digits); phone / email /
 * username must be unique on the tenant — forRun() guarantees both.
 */
const details = {
  firstBase:      'Meera',          // first name = this + 5 random letters, e.g. "MeeraQxvbz"
  last:           'Nair',
  dob:            '1995-06-15',
  gender:         'Female',
  marital:        'Single',
  roleGroup:      'Staff',
  userLevel:      'Team Member',
  reportsTo:      'Amit Kumar [progbiz0017]',
  designation:    'SOFTWARE TESTER',
  branch:         'Main Branch',
  workLocation:   'Office',
  employmentType: 'Full Time Employee',
  status:         'Active',
  joiningDate:    '2026-09-11',
  country:        'India',
  canLogin:       true,
  allBranches:    true,
};

/**
 * Build the profile for ONE run: a new first name / display name (letters
 * only) plus a unique username, email and phone (time-stamped so no two runs
 * collide). Everything else comes from `details`.
 */
function forRun() {
  const now     = Date.now();
  const stamp   = String(now).slice(-6);
  const abc     = 'abcdefghijklmnopqrstuvwxyz';
  const tag     = Array.from({ length: 5 }, () => abc[Math.floor(Math.random() * 26)]).join('');
  const first   = details.firstBase + tag[0].toUpperCase() + tag.slice(1);   // e.g. "MeeraQxvbz"
  const handle  = `${first}${stamp}`.toLowerCase();                            // e.g. "meeraqxvbz563514"
  const { firstBase, ...rest } = details;
  return {
    ...rest,
    first,
    display:  `${first} ${details.last}`,
    username: handle,
    email:    `${handle}@example.com`,
    phone:    '9' + String(now).slice(-9),            // 10 digits, unique per run
  };
}

module.exports = { details, forRun };
